import Rise from '@/components/marketing/Rise';
import { DEMO_MATCHES } from '@/lib/marketing/demo-match';

/**
 * The Discover surface, as a visitor would meet it.
 *
 * These cards are the same shape as the real ones in the product, and the
 * reasons are generated by the same engine. The point of the section is
 * the contrast underneath it: a traditional network ends at a profile and
 * a cold message, and Mentable ends at a reason and a thing to ask.
 *
 * No logo, no competitor named. If the comparison is right it does not
 * need pointing at.
 */

const TRADITIONAL = ['Search', 'Filter', 'Profile', 'Cold message', 'Hope'];
const MENTABLE = ['Understand', 'Recommend', 'Explain', 'Introduce', 'Relationship'];

export default function DiscoverShowcase() {
  const cards = DEMO_MATCHES.slice(0, 2);

  return (
    <section
      className="py-20 sm:py-24 px-6 lg:px-10 bg-halo-veil border-y border-halo-rule"
      aria-labelledby="discover-heading"
    >
      <div className="max-w-5xl mx-auto">
        <Rise kind="statement">
          <h2
            id="discover-heading"
            className="font-display text-halo-ink leading-[1.05] mb-3 max-w-xl"
            style={{ fontSize: 'clamp(1.9rem, 4vw, 2.75rem)' }}
          >
            Meet the people you should know.
          </h2>
          <p className="text-[16px] text-halo-heather leading-relaxed max-w-md mb-9">
            Ranked by relevance, backed by reasons you can check.
          </p>
        </Rise>

        <ul className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {cards.map((m) => (
            <li key={m.candidate.name} className="rounded-2xl border border-halo-rule bg-white p-5">
              <div className="flex items-start gap-3">
                <span className="flex h-10 w-10 flex-none items-center justify-center rounded-full bg-halo-deep text-[12px] font-semibold text-white">
                  {m.candidate.initials}
                </span>
                <div className="min-w-0">
                  <p className="text-[15.5px] font-medium text-halo-ink leading-snug">{m.candidate.name}</p>
                  <p className="text-[13px] text-halo-heather leading-snug mt-0.5">{m.candidate.label}</p>
                </div>
              </div>

              <p className="font-ui text-[9.5px] font-semibold uppercase tracking-[0.12em] text-halo-mist-body mt-4 mb-1.5">
                Why {m.candidate.name.split(' ')[0]}
              </p>
              <ul className="space-y-1.5">
                {m.reasons.map((r, i) => (
                  <li key={i} className="text-[14px] text-halo-ink leading-relaxed">{r}</li>
                ))}
              </ul>

              {m.opener && (
                <>
                  <p className="font-ui text-[9.5px] font-semibold uppercase tracking-[0.12em] text-halo-mist-body mt-4 mb-1.5">
                    Start here
                  </p>
                  <p className="text-[13.5px] text-halo-heather leading-relaxed">{m.opener}</p>
                </>
              )}
            </li>
          ))}
        </ul>

        {/* ── Discovery shouldn't end at a profile ─────────────────── */}
        <Rise kind="heading" delay={0.08}>
          <div className="mt-12 pt-10 border-t border-halo-rule">
            <h3 className="font-display text-halo-ink leading-tight text-[1.6rem] mb-6 max-w-md">
              Discovery shouldn&rsquo;t end at a profile.
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <Chain label="Most networks" steps={TRADITIONAL} muted />
              <Chain label="Mentable" steps={MENTABLE} />
            </div>
          </div>
        </Rise>
      </div>
    </section>
  );
}

function Chain({ label, steps, muted }: { label: string; steps: string[]; muted?: boolean }) {
  return (
    <div>
      <p className="font-ui text-[9.5px] font-semibold uppercase tracking-[0.12em] text-halo-mist-body mb-2.5">
        {label}
      </p>
      <ol className="flex flex-wrap items-center gap-x-1.5 gap-y-2">
        {steps.map((s, i) => (
          <li key={s} className="flex items-center gap-1.5">
            <span
              className={`rounded-lg border px-2.5 py-1 text-[12.5px] ${
                muted
                  ? 'border-halo-rule text-halo-mist-body'
                  : 'border-halo-brand-line/40 bg-white text-halo-ink font-medium'
              }`}
            >
              {s}
            </span>
            {i < steps.length - 1 && (
              <span className={muted ? 'text-halo-mist' : 'text-halo-brand-line'} aria-hidden="true">→</span>
            )}
          </li>
        ))}
      </ol>
    </div>
  );
}
